"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[3770],{3800:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"robocon-orc-national-finals-2025-2026","metadata":{"permalink":"/vi/blog/robocon-orc-national-finals-2025-2026","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-06-09-robocon-orc-national-finals.md","source":"@site/i18n/vi/docusaurus-plugin-content-blog/2026-06-09-robocon-orc-national-finals.md","title":"Chung k\u1ebft Robocon ORC To\xe0n qu\u1ed1c 2025\u20132026 quy t\u1ee5 g\u1ea7n 200 \u0111\u1ed9i thi","description":"Chung k\u1ebft Robocon ORC To\xe0n qu\u1ed1c 2025\u20132026 \u0111\xe3 kh\xe9p l\u1ea1i v\xe0o ng\xe0y 6\u20137/6/2026 t\u1ea1i","date":"2026-06-09T00:00:00.000Z","tags":[{"inline":false,"label":"Competition","permalink":"/vi/blog/tags/competition","description":"Competitions and contests"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":1.33,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"robocon-orc-national-finals-2025-2026","title":"Chung k\u1ebft Robocon ORC To\xe0n qu\u1ed1c 2025\u20132026 quy t\u1ee5 g\u1ea7n 200 \u0111\u1ed9i thi","authors":["aclab"],"tags":["competition","news"]},"unlisted":false,"nextItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/vi/blog/seminar-edge-ai-inspection"}},"content":"**Chung k\u1ebft Robocon ORC To\xe0n qu\u1ed1c 2025\u20132026** \u0111\xe3 kh\xe9p l\u1ea1i v\xe0o **ng\xe0y 6\u20137/6/2026** t\u1ea1i\\r\\nTr\u01b0\u1eddng \u0110\u1ea1i h\u1ecdc S\u01b0 ph\u1ea1m K\u1ef9 thu\u1eadt TP.HCM, quy t\u1ee5 **g\u1ea7n 200 \u0111\u1ed9i thi \u0111\u1ebfn t\u1eeb h\u01a1n 100 tr\u01b0\u1eddng** tr\xean\\r\\nkh\u1eafp Vi\u1ec7t Nam \u2014 m\u1ed9t \u0111i\u1ec3m nh\u1ea5n c\u1ee7a c\u1ed9ng \u0111\u1ed3ng STEM Robotics \u0111ang ph\xe1t tri\u1ec3n m\u1ea1nh trong n\u01b0\u1edbc.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## T\u1ed5ng quan\\r\\n\\r\\n- **Th\u1eddi gian:** 6\u20137/6/2026\\r\\n- **\u0110\u1ecba \u0111i\u1ec3m:** Tr\u01b0\u1eddng \u0110\u1ea1i h\u1ecdc S\u01b0 ph\u1ea1m K\u1ef9 thu\u1eadt TP.HCM\\r\\n- **Quy m\xf4:** g\u1ea7n 200 \u0111\u1ed9i t\u1eeb h\u01a1n 100 tr\u01b0\u1eddng tr\xean c\u1ea3 n\u01b0\u1edbc, t\u1eeb b\u1eadc ti\u1ec3u h\u1ecdc \u0111\u1ebfn \u0111\u1ea1i h\u1ecdc\\r\\n- **H\xecnh th\u1ee9c:** nhi\u1ec1u b\u1ea3ng \u0111\u1ea5u theo \u0111\u1ed9 tu\u1ed5i/kinh nghi\u1ec7m; c\xe1c \u0111\u1ed9i \u0111\u01b0\u1ee3c \u0111\xe1nh gi\xe1 v\u1ec1 kh\u1ea3 n\u0103ng l\u1eafp\\r\\n  r\xe1p v\xe0 l\u1eadp tr\xecnh robot, t\u01b0 duy chi\u1ebfn thu\u1eadt, x\u1eed l\xfd t\xecnh hu\u1ed1ng v\xe0 l\xe0m vi\u1ec7c nh\xf3m\\r\\n- **H\xe0nh tr\xecnh:** v\xf2ng chung k\u1ebft kh\xe9p l\u1ea1i m\u1ed9t m\xf9a gi\u1ea3i k\xe9o d\xe0i c\u1ea3 n\u0103m v\u1edbi c\xe1c v\xf2ng \u0111\u1ea5u tr\u1ef1c\\r\\n  tuy\u1ebfn v\xe0 khu v\u1ef1c\\r\\n\\r\\nS\u1ef1 ki\u1ec7n do Vi\u1ec7n Nghi\xean c\u1ee9u Thi\u1ebft k\u1ebf Tr\u01b0\u1eddng h\u1ecdc (thu\u1ed9c B\u1ed9 Gi\xe1o d\u1ee5c v\xe0 \u0110\xe0o t\u1ea1o) t\u1ed5 ch\u1ee9c, \u0111\u1ed3ng t\u1ed5\\r\\nch\u1ee9c c\xf9ng Tr\u01b0\u1eddng \u0110\u1ea1i h\u1ecdc Phan Thi\u1ebft, v\xe0 \u0111\u01b0\u1ee3c t\xe0i tr\u1ee3 b\u1edfi **OhStem Education** \u2014 m\u1ed9t trong nh\u1eefng\\r\\n[\u0111\u1ed1i t\xe1c c\u1ee7a ACLAB](/partners) trong l\u0129nh v\u1ef1c STEM v\xe0 thi \u0111\u1ea5u robotics \u2014 c\xf9ng v\u1edbi Lidinco.\\r\\n\\r\\n:::note V\xec sao ch\xfang t\xf4i chia s\u1ebb \u0111i\u1ec1u n\xe0y\\r\\nACLAB h\u1ee3p t\xe1c v\u1edbi OhStem trong c\xe1c ho\u1ea1t \u0111\u1ed9ng robotics th\u1ef1c h\xe0nh v\xe0 thi \u0111\u1ea5u. Nh\u1eefng s\u1ef1 ki\u1ec7n nh\u01b0\\r\\nth\u1ebf n\xe0y nu\xf4i d\u01b0\u1ee1ng ngu\u1ed3n nh\xe2n l\u1ef1c m\xe0 ch\xfang t\xf4i r\u1ea5t mong \u0111\u01b0\u1ee3c ch\xe0o \u0111\xf3n v\u1ec1 lab. B\u1ea1n mu\u1ed1n ch\u1ebf t\u1ea1o\\r\\nrobot thi \u0111\u1ea5u? [Tham gia ACLAB](/join).\\r\\n:::\\r\\n\\r\\nNgu\u1ed3n: [orc.vn](https://www.orc.vn/chung-ket-robocon-orc-toan-quoc-2025-2026-quy-tu-gan-200-doi-thi-tren-ca-nuoc/)"},{"id":"seminar-edge-ai-inspection","metadata":{"permalink":"/vi/blog/seminar-edge-ai-inspection","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-05-20-seminar-edge-ai.md","source":"@site/blog/2026-05-20-seminar-edge-ai.md","title":"Seminar: Edge AI for real-time visual inspection","description":"This month\'s lab seminar covers deploying quantized vision models on embedded","date":"2026-05-20T00:00:00.000Z","tags":[{"inline":false,"label":"Seminar","permalink":"/vi/blog/tags/seminar","description":"Talks and seminars"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.39,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"seminar-edge-ai-inspection","title":"Seminar: Edge AI for real-time visual inspection","authors":["aclab"],"tags":["seminar","news"]},"unlisted":false,"prevItem":{"title":"Chung k\u1ebft Robocon ORC To\xe0n qu\u1ed1c 2025\u20132026 quy t\u1ee5 g\u1ea7n 200 \u0111\u1ed9i thi","permalink":"/vi/blog/robocon-orc-national-finals-2025-2026"},"nextItem":{"title":"ACLAB team reaches national robotics competition finals","permalink":"/vi/blog/robotics-competition-finals"}},"content":"This month\'s lab seminar covers **deploying quantized vision models on embedded\\naccelerators** for real-time quality control on the factory floor.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Topics\\n\\n- Model quantization and pruning for edge devices\\n- Running inference on Jetson with TensorRT\\n- Measuring latency, throughput and power on-device\\n- A walkthrough of our visual-inspection project pipeline\\n\\nThe session is open to all lab members and interested students. Slides and demo\\ncode will be shared in the [Knowledge Base](/docs/intro) afterwards."},{"id":"robotics-competition-finals","metadata":{"permalink":"/vi/blog/robotics-competition-finals","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-04-10-robotics-competition.md","source":"@site/blog/2026-04-10-robotics-competition.md","title":"ACLAB team reaches national robotics competition finals","description":"Our autonomous AGV team reached the finals of a national robotics competition","date":"2026-04-10T00:00:00.000Z","tags":[{"inline":false,"label":"Competition","permalink":"/vi/blog/tags/competition","description":"Competitions and contests"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.355,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"robotics-competition-finals","title":"ACLAB team reaches national robotics competition finals","authors":["aclab"],"tags":["competition","news"]},"unlisted":false,"prevItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/vi/blog/seminar-edge-ai-inspection"}},"content":"Our autonomous AGV team reached the **finals of a national robotics competition**\\nwith a LiDAR-based navigation stack designed and built entirely in the lab.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Highlights\\n\\n- Differential-drive AGV with custom motor-driver PCBs\\n- LiDAR SLAM and ROS 2 navigation\\n- Real-time obstacle avoidance and path planning\\n\\nCongratulations to the team! The platform continues as one of our active\\n[projects](/projects). Want to build the next one? [Join ACLAB](/join)."}]}}')}}]);